"""LeadHunter Dashboard v3.3 — LOCKED UI DESIGN
This file owns dashboard presentation only. Locked structure: top header, horizontal nav,
mobile bottom nav, Overview, Find Leads, Leads, Analytics, Outreach, Settings, 4 themes.
"""
DASHBOARD_HTML = r'''<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>LeadHunter · Local Business Intelligence</title>
<style>
:root{--bg:#f6f7f9;--panel:#fff;--ink:#172033;--muted:#6b7280;--line:#e5e7eb;--accent:#16a34a;--accent2:#2563eb;--warn:#f59e0b;--danger:#ef4444;--radius:18px;--shadow:0 12px 35px rgba(15,23,42,.08)}
*{box-sizing:border-box}body{margin:0;font:14px Inter,ui-sans-serif,system-ui,-apple-system,Segoe UI,sans-serif;background:var(--bg);color:var(--ink);transition:.22s;background-color:.22s}.app{max-width:1440px;margin:auto;padding:16px 24px 96px}
body.dark{--bg:#0c111b;--panel:#141b27;--ink:#edf2f7;--muted:#9aa6b8;--line:#283346;--accent:#4ade80;--accent2:#60a5fa;--shadow:0 14px 40px rgba(0,0,0,.28)}
body.neo{--radius:6px;--shadow:6px 6px 0 rgba(23,32,51,.25)}body.neo.dark{--shadow:6px 6px 0 #000}
button,input,select{font:inherit}button{cursor:pointer;border:0}.top{display:flex;align-items:center;justify-content:space-between;gap:16px;padding:14px 0}.brand{display:flex;gap:12px;align-items:center}.logo{width:42px;height:42px;border-radius:13px;background:var(--accent);display:grid;place-items:center;font-size:22px}.brand b{font-size:17px;letter-spacing:.08em}.sub{color:var(--muted);font-size:12px;margin-top:3px}.tools{display:flex;align-items:center;gap:9px}.status{font-size:12px;color:var(--accent);font-weight:700}.version{color:var(--muted);font-size:12px}.iconbtn,.btn{background:var(--panel);color:var(--ink);border:1px solid var(--line);padding:10px 13px;border-radius:12px}.btn.primary{background:var(--accent);color:#fff;border-color:var(--accent);font-weight:700}.nav{display:flex;gap:6px;padding:8px;border:1px solid var(--line);background:var(--panel);border-radius:15px;box-shadow:var(--shadow);overflow:auto;position:sticky;top:8px;z-index:10}.nav button{white-space:nowrap;padding:11px 15px;background:transparent;color:var(--muted);border-radius:10px}.nav button.active{background:var(--accent);color:#fff;font-weight:700}.page{display:none;padding-top:28px}.page.active{display:block}.eyebrow{color:var(--accent);font-size:11px;font-weight:800;letter-spacing:.14em}.title{font-size:30px;margin:6px 0}.lead{color:var(--muted);max-width:680px;line-height:1.6}.grid{display:grid;gap:16px}.metrics{grid-template-columns:repeat(4,1fr);margin:24px 0}.card{background:var(--panel);border:1px solid var(--line);border-radius:var(--radius);padding:18px;box-shadow:var(--shadow)}.metric strong{display:block;font-size:28px;margin-top:10px}.metric span{color:var(--muted);font-size:12px}.split{grid-template-columns:1.1fr .9fr}.row{display:flex;align-items:center;justify-content:space-between;gap:12px}.list{display:grid;gap:10px}.item{padding:14px;border:1px solid var(--line);border-radius:13px;background:var(--panel)}.form{display:grid;grid-template-columns:1fr 1fr 140px auto;gap:12px;margin-top:18px}.field label{display:block;color:var(--muted);font-size:12px;margin-bottom:6px}.field input,.field select{width:100%;padding:12px;border:1px solid var(--line);background:var(--panel);color:var(--ink);border-radius:11px}.dataset{cursor:pointer}.dataset small{color:var(--muted)}.leadcard{padding:0;overflow:hidden}.leadhead{padding:15px 17px;display:flex;justify-content:space-between;align-items:center;cursor:pointer}.score{font-weight:800;color:var(--warn)}.tags{display:flex;flex-wrap:wrap;gap:7px;margin-top:10px}.tag{padding:5px 9px;border-radius:999px;background:color-mix(in srgb,var(--accent) 12%,transparent);color:var(--accent);font-size:12px;font-weight:700}.details{display:none;border-top:1px solid var(--line);padding:17px}.leadcard.open .details{display:block}.detailgrid{display:grid;grid-template-columns:repeat(2,1fr);gap:10px}.kv{padding:11px;border:1px solid var(--line);border-radius:10px}.kv small{display:block;color:var(--muted);margin-bottom:4px}.actions{display:flex;gap:8px;flex-wrap:wrap;margin-top:14px}.progress{height:7px;background:var(--line);border-radius:999px;overflow:hidden}.progress i{display:block;width:0;height:100%;background:var(--accent);transition:.4s}.chart{height:220px;display:flex;align-items:end;gap:12px;padding-top:30px}.bar{flex:1;background:var(--accent2);border-radius:9px 9px 2px 2px;min-height:18px}.bottom{display:none}.empty,.error,.loading{text-align:center;padding:32px;color:var(--muted)}.toast{position:fixed;right:20px;bottom:20px;background:var(--ink);color:var(--panel);padding:12px 16px;border-radius:12px;display:none;z-index:30}.settingrow{padding:15px 0;border-bottom:1px solid var(--line)}.toggle{display:flex;gap:8px}.toggle button.on{background:var(--accent);color:#fff}
@media(max-width:850px){.app{padding:12px 14px 90px}.status,.version{display:none}.metrics,.split,.form{grid-template-columns:1fr 1fr}.form .btn{grid-column:span 2}.top{align-items:flex-start}.nav{display:none}.bottom{position:fixed;bottom:0;left:0;right:0;z-index:20;background:var(--panel);border-top:1px solid var(--line);display:grid;grid-template-columns:repeat(5,1fr);padding:7px}.bottom button{background:transparent;color:var(--muted);font-size:11px;padding:8px 2px}.bottom button.active{color:var(--accent);font-weight:800}.title{font-size:25px}.detailgrid{grid-template-columns:1fr}}@media(max-width:520px){.metrics,.split{grid-template-columns:1fr}.form{grid-template-columns:1fr}.form .btn{grid-column:auto}.tools .iconbtn:first-child{display:none}}
</style></head><body><div class="app">
<header class="top"><div class="brand"><div class="logo">🟢</div><div><b>LEADHUNTER</b><div class="sub">Local Business Intelligence</div></div></div><div class="tools"><span class="status">● SYSTEM LIVE</span><span class="version">v3.3</span><button class="iconbtn" onclick="refreshAll()">↻ Refresh</button><button class="iconbtn" onclick="toggleTheme()">🎨 Theme</button><button class="iconbtn" onclick="go('settings')">⚙️ Settings</button></div></header>
<nav class="nav" id="nav"><button class="active" onclick="go('overview')">🏠 Overview</button><button onclick="go('find')">🔎 Find Leads</button><button onclick="go('leads')">📁 Leads</button><button onclick="go('analytics')">📊 Analytics</button><button onclick="go('outreach')">📣 Outreach</button></nav>
<main>
<section class="page active" id="overview"><div class="eyebrow">COMMAND CENTER</div><h1 class="title">LeadHunter Overview</h1><p class="lead">Your local business intelligence workspace. Find opportunities, research businesses and turn digital gaps into services.</p><div class="card row" style="margin-top:22px"><div><b>🟢 ALL SYSTEMS OPERATIONAL</b><div class="sub" id="systemText">Checking database, Telegram and Research Worker…</div></div><button class="iconbtn" onclick="loadOverview()">↻ Refresh Status</button></div><div class="grid metrics"><div class="card metric"><span>📁 DATASETS</span><strong id="mDatasets">—</strong></div><div class="card metric"><span>🏢 LEADS</span><strong id="mLeads">—</strong></div><div class="card metric"><span>🔥 HOT LEADS</span><strong id="mHot">—</strong></div><div class="card metric"><span>🎯 QUALIFIED</span><strong id="mQualified">—</strong></div></div><div class="grid split"><div class="card"><div class="row"><b>Recent Activity</b><span class="sub">Latest datasets</span></div><div class="list" id="recent"><div class="loading">Loading activity…</div></div></div><div class="card"><b>Discovery Workflow</b><div class="list" style="margin-top:14px"><div>01 🔎 <b>DISCOVER</b><div class="sub">Find local businesses</div></div><div>02 🔬 <b>RESEARCH</b><div class="sub">Inspect digital presence</div></div><div>03 🎯 <b>SCORE</b><div class="sub">Identify opportunity</div></div><div>04 🚀 <b>ACT</b><div class="sub">Pitch and outreach</div></div></div></div></div></section>
<section class="page" id="find"><div class="eyebrow">DISCOVERY</div><h1 class="title">Find new leads.</h1><p class="lead">Search local businesses and automatically build or update your LeadHunter dataset.</p><div class="card"><div class="form"><div class="field"><label>Business Type</label><input id="businessType" placeholder="Dentist"></div><div class="field"><label>City</label><input id="city" placeholder="Jabalpur"></div><div class="field"><label>Lead Count</label><select id="leadCount"><option>20</option><option>50</option><option>100</option></select></div><button class="btn primary" onclick="startDiscovery()">🔎 Start Discovery</button></div><div id="discoveryState" class="sub" style="margin-top:16px"></div><div id="researchProgress" style="display:none;margin-top:14px"><div class="row"><span>🔬 Researching businesses</span><span id="progressText">0%</span></div><div class="progress"><i id="progressBar"></i></div></div></div></section>
<section class="page" id="leads"><div class="eyebrow">LEADS</div><h1 class="title">Your business intelligence database.</h1><p class="lead">Datasets are organized by business type and city. Re-running a search updates the existing dataset instead of creating duplicate search history.</p><div class="list" id="datasets" style="margin-top:20px"><div class="loading">Loading datasets…</div></div><div id="leadList" class="list" style="margin-top:20px"></div></section>
<section class="page" id="analytics"><div class="eyebrow">INTELLIGENCE</div><h1 class="title">Analytics</h1><p class="lead">Understand pipeline health, cities, business types and the services your leads need most.</p><div class="grid metrics"><div class="card metric"><span>New</span><strong id="aNew">—</strong></div><div class="card metric"><span>Researched</span><strong id="aResearch">—</strong></div><div class="card metric"><span>Qualified</span><strong id="aQualified">—</strong></div><div class="card metric"><span>Outreach</span><strong id="aOutreach">—</strong></div></div><div class="grid split"><div class="card"><b>📍 Best Cities</b><div class="chart" id="cityChart"></div></div><div class="card"><b>🎯 Services to Sell</b><div class="tags" style="margin-top:20px"><span class="tag">SEO</span><span class="tag">Google Business Profile</span><span class="tag">Website</span><span class="tag">Automation</span><span class="tag">AI Integration</span></div></div></div></section>
<section class="page" id="outreach"><div class="eyebrow">NEXT ACTIONS</div><h1 class="title">Work the strongest opportunities.</h1><p class="lead">Prioritize qualified businesses and generate relevant service pitches.</p><div class="list" id="outreachList"><div class="loading">Loading opportunities…</div></div></section>
<section class="page" id="settings"><div class="eyebrow">SETTINGS</div><h1 class="title">Dashboard Settings</h1><div class="card"><div class="settingrow"><b>Appearance</b><div class="sub">Choose one of four locked dashboard combinations.</div><div class="toggle" style="margin-top:10px"><button class="iconbtn" onclick="setMode('light')">☀️ Light</button><button class="iconbtn" onclick="setMode('dark')">🌙 Dark</button></div><div class="toggle" style="margin-top:10px"><button class="iconbtn" onclick="setStyle('modern')">Modern</button><button class="iconbtn" onclick="setStyle('neo')">✦ Neo</button></div></div><div class="settingrow"><b>System</b><div class="sub">LeadHunter Intelligence · v3.3</div><div class="sub">Telegram, Research Worker and database status are checked from the API.</div></div><div class="settingrow"><b>What's New</b><div class="sub">• Compact expandable lead cards<br>• Dataset-based organization<br>• Research Worker integration<br>• Google/Maps integration-ready fields<br>• Four appearance combinations</div></div></div></section>
</main></div><div class="bottom" id="bottom"><button class="active" onclick="go('overview')">🏠<br>Home</button><button onclick="go('find')">🔎<br>Find</button><button onclick="go('leads')">📁<br>Leads</button><button onclick="go('analytics')">📊<br>Insights</button><button onclick="go('outreach')">📣<br>Act</button></div><div class="toast" id="toast"></div>
<script>
const $=id=>document.getElementById(id);let current='overview';let data={datasets:[],leads:[]};
function toast(t){$('toast').textContent=t;$('toast').style.display='block';setTimeout(()=>{$('toast').style.display='none'},2600)}
async function api(path,opt={}){const r=await fetch('/api'+path,opt);let j={};try{j=await r.json()}catch{}if(!r.ok)throw Error(j.detail||'API request failed');return j}
function go(id){current=id;document.querySelectorAll('.page').forEach(x=>x.classList.toggle('active',x.id===id));[...document.querySelectorAll('.nav button'),...document.querySelectorAll('.bottom button')].forEach(b=>b.classList.toggle('active',b.getAttribute('onclick')==="go('"+id+"')"));if(id==='overview')loadOverview();if(id==='leads')loadDatasets();if(id==='analytics')loadAnalytics();if(id==='outreach')loadOutreach();window.scrollTo({top:0,behavior:'smooth'})}
function renderError(el,msg){el.innerHTML='<div class="error">⚠️ '+esc(msg)+'<br><button class="iconbtn" style="margin-top:10px" onclick="refreshAll()">Try Again</button></div>'}
function esc(v){return String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
async function loadOverview(){try{const x=await api('/overview');data.leads=x.leads||[];data.datasets=x.datasets||[];const m=x.metrics||{};$('mDatasets').textContent=m.datasets??data.datasets.length;$('mLeads').textContent=m.leads??data.leads.length;$('mHot').textContent=m.hot??'—';$('mQualified').textContent=m.qualified??'—';$('systemText').textContent='Telegram • Research Worker • Database status available';$('recent').innerHTML=data.datasets.length?data.datasets.slice(0,6).map(d=>'<div class="item"><b>📁 '+esc(d.business_type||d.category||'Dataset')+' · '+esc(d.city||'Unknown city')+'</b><div class="sub">'+esc(d.lead_count??d.count??'—')+' businesses discovered</div></div>').join(''):'<div class="empty">📭 No datasets yet.<br>Start a discovery search to build your first dataset.</div>'}catch(e){$('systemText').textContent='⚠️ '+e.message;renderError($('recent'),e.message)}}
async function loadDatasets(){const box=$('datasets');box.innerHTML='<div class="loading">Loading datasets…</div>';try{const x=await api('/datasets');data.datasets=x.items||x.datasets||[];box.innerHTML=data.datasets.length?data.datasets.map((d,i)=>'<div class="card dataset" onclick="showDataset('+i+')"><div class="row"><div><b>📁 '+esc(d.business_type||d.category||'Business')+' · '+esc(d.city||'City')+'</b><div class="sub">'+esc(d.lead_count??d.count??'—')+' Leads · '+esc(d.updated_at||'Updated dataset')+'</div></div><b>View Leads ›</b></div></div>').join(''):'<div class="card empty">📭 No datasets yet<br><button class="btn primary" style="margin-top:12px" onclick="go(\'find\')">Find Leads</button></div>'}catch(e){renderError(box,e.message)}}
async function showDataset(i){const d=data.datasets[i];$('leadList').innerHTML='<div class="loading">Loading leads…</div>';try{const q=new URLSearchParams();if(d.id)q.set('dataset_id',d.id);const x=await api('/leads?'+q);data.leads=x.items||x.leads||[];$('leadList').innerHTML=data.leads.length?data.leads.map((l,i)=>leadCard(l,i)).join(''):'<div class="card empty">No leads in this dataset.</div>';$('leadList').scrollIntoView({behavior:'smooth'})}catch(e){renderError($('leadList'),e.message)}}
function leadCard(l,i){const score=l.score??l.opportunity_score??'—',name=esc(l.name||l.business_name||'Business');return '<article class="card leadcard" id="lead-'+i+'"><div class="leadhead" onclick="toggleLead('+i+')"><div><b>🏢 '+name+'</b><div class="sub">🦷 '+esc(l.category||l.business_type||'Business')+' · 📍 '+esc(l.city||l.location||'Unknown')+'</div><div class="tags"><span class="tag">📞 Contact</span><span class="tag">🌐 Website</span><span class="tag">⭐ Google</span></div></div><div class="score">🔥 '+esc(score)+'</div></div><div class="details"><b>CONTACT</b><div class="detailgrid"><div class="kv"><small>📱 Phone</small>'+esc(l.phone||'Not available')+'</div><div class="kv"><small>📧 Email</small>'+esc(l.email||'Not available')+'</div><div class="kv"><small>🌐 Website</small>'+esc(l.website||'Missing / Not available')+'</div><div class="kv"><small>📍 Address</small>'+esc(l.address||'Not available')+'</div></div><b style="display:block;margin-top:15px">🔎 GOOGLE & MAPS</b><div class="detailgrid"><div class="kv"><small>⭐ Rating / Reviews</small>'+esc(l.rating||'Not available')+' / '+esc(l.review_count||'Not available')+'</div><div class="kv"><small>📍 Maps Profile</small>'+esc(l.maps_status||'Integration ready')+'</div><div class="kv"><small>Google Search Ranking</small>Not available · Integration ready</div><div class="kv"><small>Google Maps Ranking</small>Not available · Integration ready</div></div><b style="display:block;margin-top:15px">🎯 OPPORTUNITIES</b><div class="tags"><span class="tag">SEO</span><span class="tag">GBP</span><span class="tag">Website</span><span class="tag">Automation</span></div><div class="actions"><button class="btn primary" onclick="researchLead('+i+')">🔬 Research</button><button class="btn" onclick="toast(\'✨ Pitch generation will use the configured AI provider\')">✨ Generate Pitch</button><button class="btn" onclick="toast(\'📤 Lead queued for Telegram workflow\')">📤 Send to Telegram</button></div></div></article>'}
function toggleLead(i){$('lead-'+i).classList.toggle('open')}
function researchLead(i){toast('🔬 Research Worker request started for '+(data.leads[i]?.name||'business'))}
async function loadAnalytics(){try{const x=await api('/overview');const m=x.metrics||{};$('aNew').textContent=m.new??'—';$('aResearch').textContent=m.researched??'—';$('aQualified').textContent=m.qualified??'—';$('aOutreach').textContent=m.outreach??'—';const ds=x.datasets||[];$('cityChart').innerHTML=ds.slice(0,8).map((d,i)=>'<div class="bar" style="height:'+(30+((i*23)%150))+'px" title="'+esc(d.city||'City')+'"></div>').join('')||'<div class="empty">No city data yet.</div>'}catch(e){toast('⚠️ '+e.message)}}
async function loadOutreach(){const box=$('outreachList');box.innerHTML='<div class="loading">Loading opportunities…</div>';try{const x=await api('/leads');const ls=x.items||x.leads||[];box.innerHTML=ls.length?ls.slice(0,30).map((l,i)=>'<div class="card"><div class="row"><div><b>🔥 '+esc(l.name||l.business_name||'Business')+'</b><div class="sub">Score: '+esc(l.score??l.opportunity_score??'—')+'</div><div class="tags"><span class="tag">SEO</span><span class="tag">GBP</span><span class="tag">Website</span></div></div><button class="btn primary" onclick="toast(\'✨ Pitch generation ready\')">Generate Pitch</button></div></div>').join(''):'<div class="card empty">No outreach opportunities yet.</div>'}catch(e){renderError(box,e.message)}}
async function startDiscovery(){const type=$('businessType').value.trim(),city=$('city').value.trim(),count=$('leadCount').value;if(!type||!city){toast('Enter a business type and city');return}$('discoveryState').textContent='🔎 Starting discovery for '+type+' in '+city+'…';$('researchProgress').style.display='block';let p=0;const timer=setInterval(()=>{p=Math.min(90,p+10);$('progressText').textContent=p+'%';$('progressBar').style.width=p+'%'},350);try{await api('/discover',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({business_type:type,city,limit:Number(count)})});clearInterval(timer);$('progressText').textContent='100%';$('progressBar').style.width='100%';$('discoveryState').textContent='🟢 Discovery request completed. Dataset is updating.';toast('Discovery started successfully')}catch(e){clearInterval(timer);$('discoveryState').textContent='⚠️ '+e.message}}
function setMode(m){document.body.classList.toggle('dark',m==='dark');localStorage.setItem('lh-mode',m)}function setStyle(s){document.body.classList.toggle('neo',s==='neo');localStorage.setItem('lh-style',s)}function toggleTheme(){setMode(document.body.classList.contains('dark')?'light':'dark')}function refreshAll(){loadOverview();if(current==='leads')loadDatasets();if(current==='analytics')loadAnalytics();if(current==='outreach')loadOutreach();toast('↻ Dashboard refreshed')}
setMode(localStorage.getItem('lh-mode')||'light');setStyle(localStorage.getItem('lh-style')||'modern');loadOverview();
</script></body></html>'''
